INSERT OR IGNORE INTO stones (id,name,tagline,story,born,creator,image,theme,color,is_demo,code_hash,demo_code) VALUES ('A1','Sunny Side','Let me brighten your day.','Nina painted my smile in Petržalka and left me in Sad Janka Kráľa. I’ve been collecting happy moments ever since. Could you take me somewhere sunny?','2025-04-12','Nina','stone-1.svg','sun','#c5a34d',1,'94bcfe105ad50803f9a5dc7f60974e21d47f608826675250c699467f116608dc','8451');
