INSERT OR IGNORE INTO comments (id,stone_id,find_id,created_at,nickname,message) VALUES ('comment-seed-A1-1','A1','seed-A1-1','2025-04-12T00:00:00.000Z','Nina','Painted this on a rainy morning. Left it by the park path for its first adventure.');
